-- Non-WSQ (C-prefix) course topics -> headings only, "Topic N: <title>" (owner's sample:
-- chatgpt-work-for-digital-marketing.html, 2026-10-05). Built from the LIVE description of every
-- enabled C course after 1784: keeps the real topic rows (drops LU group rows, exam-code rows and
-- "Mode/Final Assessment"), strips "Domain N"/"LU N"/"1.0"/"Section I -" prefixes and "(13%)" weights,
-- renumbers, and drops every sub-bullet. Written in the Edit Course LSN_DATA format so the admin topic
-- editor still round-trips. C818 (the sample) is left as is. Only rows whose value changes are touched.
-- Guard: TRIM(sku) + live CHAR_LENGTH (a newer edit is never clobbered; re-run = no-op). SG-only.
-- Post-deploy: flat reindex + cache flush.

SET @sg := (SELECT COUNT(*) FROM core_store WHERE store_id = 1 AND code = 'singapore');
SET @a_desc := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'description');

-- C6 AI Powered Wordpress eCommerce
UPDATE catalog_product_entity_text t JOIN catalog_product_entity e ON e.entity_id = t.entity_id SET t.value = '<!-- LSN_DATA: [{"title": "Topic 1: AI-Enabled eCommerce Store Setup and Content Management", "subsecs": []}, {"title": "Topic 2: AI-Assisted Product Catalogue and Web Content Management", "subsecs": []}, {"title": "Topic 3: Payment, Shipping and Customer Experience Optimisation", "subsecs": []}, {"title": "Topic 4: AI-Powered Sales, Order and Promotion Management", "subsecs": []}, {"title": "Topic 5: eCommerce Analytics and Performance Optimisation", "subsecs": []}] -->\n<p><strong>Topic 1: AI-Enabled eCommerce Store Setup and Content Management</strong></p>\n<p><strong>Topic 2: AI-Assisted Product Catalogue and Web Content Management</strong></p>\n<p><strong>Topic 3: Payment, Shipping and Customer Experience Optimisation</strong></p>\n<p><strong>Topic 4: AI-Powered Sales, Order and Promotion Management</strong></p>\n<p><strong>Topic 5: eCommerce Analytics and Performance Optimisation</strong></p>\n' WHERE @sg = 1 AND t.attribute_id = @a_desc AND t.store_id = 0 AND TRIM(e.sku) = 'C6' AND CHAR_LENGTH(t.value) = 888;

